  const sx = x+wx, sy = y+wy;
  const src = [
    [120+Math.sin(t*0.5)*110, 70+Math.cos(t*0.35)*45, 0.075, 2.1],
    [360+Math.cos(t*0.45)*100, 170+Math.sin(t*0.6)*55, 0.09, 1.8],
